/**
 * Labels from the fact-check reviews, with the verdict each pair got and the EN and FR claim texts at that time.
 * Used to measure a ranking (`evaluate.ts`, `lab/`) and to leave reviewed pairs out of the next review.
 *
 * - Pass 1 (docs/facts/2026-10-05-fact-check.md): the 80 riskiest pairs of the first full run (out/full).
 * - Pass 2 (docs/facts/2026-10-05-fact-check-pass2.md): the next 100 pairs of the pass-2 run (out/pass2), after the
 *   pass-1 pairs were removed. Built from lab/labels/next100.json (review order and keys) and the final verdicts in
 *   the report. `rank` is the review rank within each pass.
 *
 * Verdicts: `confirmed` = error or imprecise, confirmed after a refutation pass (the copy was fixed);
 * `refuted` = marked imprecise, then proved correct; `unsourced` = true, but the cited sources did not state it
 * (a source was added); `supported` = the cited sources state it. `retrievalMiss`: supported, but retrieval did not
 * find the passage that states it.
 */
export type Verdict = "confirmed" | "refuted" | "unsourced" | "supported";
export type ReviewedPair = { rank: number; pairKey: string; verdict: Verdict; retrievalMiss?: boolean; en: string[]; fr: string[] };
export type LabelledPair = ReviewedPair & { pass: 1 | 2 };

